/**
 * The blog's hand-drawn SVGs come in two palettes: `/blog/x.svg` (light) and
 * `/blog/x-dark.svg` (dark, generated by `npm run og:assets`). This renders
 * both and lets CSS show the one for the active theme (see .theme-*-only in
 * globals.css). The hidden copy is lazy-loaded, so it isn't downloaded.
 * Any other image renders as a plain <img>.
 */
export const darkVariant = (src = "") =>
  /^\/blog\/.+\.svg$/.test(src) && !src.endsWith("-dark.svg")
    ? src.replace(/\.svg$/, "-dark.svg")
    : null;

export default function ThemedImage({
  src,
  alt = "",
  className = "",
  loading,
  ...props
}) {
  const dark = darkVariant(src);
  if (!dark) {
    return (
      // eslint-disable-next-line @next/next/no-img-element
      <img src={src} alt={alt} className={className} loading={loading} {...props} />
    );
  }
  return (
    <>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={src}
        alt={alt}
        className={`theme-light-only ${className}`}
        loading={loading}
        {...props}
      />
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={dark}
        alt={alt}
        className={`theme-dark-only ${className}`}
        loading="lazy"
        {...props}
      />
    </>
  );
}
